insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_132'
from (values
('127.881.d.1.A',3,'A paint-shop apprentice explains a color delay to an upset customer in plain words and then confirms the plan in a text. This shows:','["effective oral and written communication with customers, coworkers and vendors", "hiding the delay", "avoiding the customer", "using only slang"]'::jsonb,0,'Clear spoken and written updates.','original'),
('127.881.d.1.A',4,'Which habit best shows effective communication in a refinish shop?','["Skipping notes to save time", "Repeating a customer''s request back and noting it on the work order", "Talking only to coworkers", "Guessing what the customer wants"]'::jsonb,1,'Confirm and document.','original'),
('127.881.d.1.B',3,'A painter fills in the paint code, number of panels and materials used on a refinish order so the office can bill. This is:','["a sales pitch", "a drawing exercise", "technical writing used to complete paint and refinishing orders", "a safety drill"]'::jsonb,2,'Orders need accurate details.','original'),
('127.881.d.1.B',4,'A refinish order that leaves out the mixing ratio can cause:','["a bigger discount", "a faster repair", "a cleaner booth", "a repeat job or a mismatched color"]'::jsonb,3,'Missing data causes rework.','original'),
('127.881.d.1.C',3,'Before spraying a new waterborne basecoat, Tomas reads the technical data sheet for flash times and reducer. He is:','["locating, reading and interpreting technical documents", "ignoring directions", "guessing times", "watching a video only"]'::jsonb,0,'The TDS gives product directions.','original'),
('127.881.d.1.C',4,'A technical data sheet is the best source for a product''s:','["owner''s name", "mix ratio, recoat window and drying times", "insurance claim", "shop hours"]'::jsonb,1,'TDS holds product specs.','original'),
('127.881.d.1.D',3,'A service bulletin says a clearcoat batch needs a different activator. A painter checks the bulletin before mixing. This shows:','["skipping updates", "relying on memory", "competency in using and interpreting service repair bulletins", "ignoring the batch"]'::jsonb,2,'Bulletins carry updates.','original'),
('127.881.d.1.D',4,'Service bulletins matter to refinish technicians because they:','["replace the training manual", "are advertising", "list paint prices only", "announce corrections or changes to products and procedures"]'::jsonb,3,'Stay current.','original'),
('127.881.d.2.A',3,'A shop plans a spot repair for one scratch and a full repaint for a faded roof. The painter is choosing:','["the basic types of refinishing procedures for the damage", "a tire size", "an oil grade", "a wheel alignment"]'::jsonb,0,'Match procedure to damage.','original'),
('127.881.d.2.A',4,'Blending into an adjacent panel is mainly done to:','["dry the paint", "hide the color transition so the repair is invisible", "add thickness", "remove rust"]'::jsonb,1,'Blends hide edges.','original'),
('127.881.d.2.B',3,'A student preps a fender, primes it, applies base and clear, then lets it cure per the data sheet. She is demonstrating:','["engine tuning", "tire mounting", "proper preparation, application and refinishing with various paint systems", "brake service"]'::jsonb,2,'Prep, apply, cure.','original'),
('127.881.d.2.B',4,'Switching from a solvent system to a waterborne system changes the need for:','["a different customer", "no changes at all", "a new car", "different flash-off, equipment and air movement"]'::jsonb,3,'Systems differ.','original'),
('127.881.d.2.C',3,'A painter adds 3.5 refinish hours at $48 per hour and $120 in materials to a paint order. The total is:','["$288", "$403.50", "$168", "$120"]'::jsonb,0,'3.5 × 48 = 168; plus 120 = 288.','original'),
('127.881.d.2.C',4,'Estimating paint cost requires counting labor hours and:','["tire wear", "material charges for primer, base and clear", "the radio", "the customer''s age"]'::jsonb,1,'Labor plus materials.','original'),
('127.881.d.2.D',3,'A painter measures 4 parts paint, 1 part activator and 1 part reducer with a ratio stick. She is performing:','["a free pour", "guesswork", "precision measurements of paint and materials", "a visual guess"]'::jsonb,2,'Measure exactly.','original'),
('127.881.d.2.D',4,'A 6-ounce batch mixed at 2:1:1 uses how much of the paint component?','["2 ounces", "1 ounce", "6 ounces", "3 ounces"]'::jsonb,3,'Paint is 2 of 4 parts, so half.','original'),
('127.881.d.3.A',3,'Before spraying, a painter reads the safety data sheet and notes isocyanate exposure risks. She is:','["identifying safety and personal health hazards according to OSHA regulations", "guessing", "ignoring labels", "skipping the sheet"]'::jsonb,0,'Know the hazards.','original'),
('127.881.d.3.A',4,'Isocyanates in activators are a health concern mainly because they can:','["improve breathing", "cause asthma-like lung reactions and skin sensitization", "clean the lungs", "cool the skin"]'::jsonb,1,'Isocyanate hazard.','original'),
('127.881.d.3.B',3,'Before a shift, a painter checks that the booth''s filters are clean and the airflow is within specification. She is:','["painting the booth", "ignoring filters", "inspecting the spray environment for compliance with federal, state and local regulations", "cleaning the lobby"]'::jsonb,2,'Booth compliance.','original'),
('127.881.d.3.B',4,'A spray booth with clogged filters can cause:','["cleaner air", "less overspray", "faster curing only", "poor airflow, dirt in the finish and unsafe fumes"]'::jsonb,3,'Filters matter.','original'),
('127.881.d.3.C',3,'Sandra puts on a fitted respirator, checks the seal and checks cartridge dates before mixing. She is:','["selecting, using, inspecting and maintaining respiratory equipment per OSHA standards", "using a paper dust mask", "skipping a fit check", "sharing masks"]'::jsonb,0,'Respirator fit and care.','original'),
('127.881.d.3.C',4,'A fit check on a respirator is done to make sure:','["the mask is colorful", "no air leaks around the seal", "the mask is loud", "the mask looks new"]'::jsonb,1,'Seal check.','original'),
('127.881.d.3.D',3,'A shop uses an air-supplied hood for waterborne and solvent spraying, tests the air quality and logs maintenance. This follows:','["a paint brand''s ad", "a customer''s request", "OSHA Regulation 1910.134 on respiratory protection", "a school dress code"]'::jsonb,2,'Respiratory standard.','original'),
('127.881.d.3.D',4,'Records of respirator fit testing and maintenance are kept to:','["save paper", "hide mistakes", "reduce training", "show compliance and protect worker health"]'::jsonb,3,'Documentation.','original'),
('127.881.d.3.E',3,'A painter chooses nitrile gloves, a paint suit and a hood with the respirator. She is:','["selecting and using proper personal safety equipment", "skipping a suit", "wearing sandals", "wearing cotton gloves"]'::jsonb,0,'PPE selection.','original'),
('127.881.d.3.E',4,'Nitrile gloves are preferred over latex for paints because they:','["are free", "resist solvents and avoid latex allergies", "dissolve instantly", "absorb paint"]'::jsonb,1,'Solvent resistance.','original'),
('127.881.d.3.F',3,'Luis checks the cord of a random orbital sander and uses the dust extraction hose. He is using:','["no tools", "only a spray gun", "hand and power tools and equipment commonly used in paint and refinishing", "only a brush"]'::jsonb,2,'Tool safety.','original'),
('127.881.d.3.F',4,'Before using a power sander, a technician should:','["remove the guard", "hold it by the cord", "use it wet", "inspect it for damage and keep guards in place"]'::jsonb,3,'Inspect first.','original'),
('127.881.d.3.G',3,'A shop collects used thinner and sets rags in a closed metal can instead of the trash. This is:','["proper handling and disposal of environmentally hazardous materials", "dumping in the drain", "burning rags", "ignoring regulations"]'::jsonb,0,'Hazmat disposal.','original'),
('127.881.d.3.G',4,'Solvent-soaked rags are stored in a closed approved container to prevent:','["faster drying", "fire from spontaneous combustion and vapor release", "rag shortages", "cleaner floors"]'::jsonb,1,'Fire prevention.','original'),
('127.881.d.3.H',3,'A shop evaluates a new low-VOC waterborne system and an infrared curing lamp. This shows:','["outdated methods only", "resistance to change", "knowledge of new and emerging paint and refinishing technologies", "avoiding training"]'::jsonb,2,'Emerging tech.','original'),
('127.881.d.3.H',4,'Waterborne basecoat is chosen in many shops because it:','["needs no training", "raises VOCs", "is the cheapest option always", "lowers volatile organic compound emissions"]'::jsonb,3,'Environmental benefit.','original'),
('127.881.d.4.A',3,'The shop manager walks the booth monthly with a checklist covering ventilation, storage and eyewash stations. She is:','["performing regular audits and inspections to maintain compliance with safety, health and environmental regulations", "painting", "skipping inspections", "guessing"]'::jsonb,0,'Audits catch problems.','original'),
('127.881.d.4.A',4,'Regular audits help a shop avoid:','["productivity", "fines, injuries and shutdowns", "compliance", "safe work"]'::jsonb,1,'Prevent violations.','original'),
('127.881.d.4.B',3,'A painter finds a hood is aluminum and a bumper is plastic and adjusts the prep for each. She is:','["ignoring materials", "using one method for all", "inspecting vehicle construction materials and the associated refinishing methods", "guessing"]'::jsonb,2,'Materials differ.','original'),
('127.881.d.4.B',4,'Aluminum panels need different preparation than steel because aluminum:','["is a plastic", "needs no prep", "never corrodes", "forms an oxide layer and needs specific cleaners and primers"]'::jsonb,3,'Aluminum prep.','original'),
('127.881.d.4.C',3,'A technician sees the paint is a factory single-stage finish on an older truck and chooses a compatible refinish plan. She is:','["identifying different types of vehicle finishes and associated refinish techniques", "ignoring the finish", "skipping prep", "guessing"]'::jsonb,0,'Know the finish.','original'),
('127.881.d.4.C',4,'A solvent-wipe test on an old paint finish helps determine if it is:','["wet or dry", "lacquer or enamel", "new or old oil", "steel or aluminum"]'::jsonb,1,'Finish ID.','original'),
('127.881.d.4.D',3,'A painter spots tiny circles around a sanding scratch and traces them back to feather-edging with coarse paper. She is:','["hiding it", "painting over it", "inspecting, identifying and determining the cause of a paint defect", "ignoring it"]'::jsonb,2,'Find the cause.','original'),
('127.881.d.4.D',4,'Fisheyes in a fresh finish are usually caused by:','["clean metal", "cold booth only", "too much hardener", "surface contamination such as silicone or wax"]'::jsonb,3,'Contamination.','original'),
('127.881.d.4.E',3,'A shop applies seam sealer and cavity wax after a panel replacement so moisture can''t reach bare metal. They are discussing:','["corrosion protection", "wheel balance", "engine tuning", "glass care"]'::jsonb,0,'Rust protection.','original'),
('127.881.d.4.E',4,'Corrosion protection is restored after repairs because it:','["removes paint", "prevents rust from starting at the repaired area", "speeds the job", "adds weight"]'::jsonb,1,'Protect repaired metal.','original'),
('127.881.d.4.F',3,'After refinishing, a detailer washes the car, cleans the glass and wipes door jambs. She is:','["sanding filler", "spraying primer", "demonstrating vehicle detailing", "mixing paint"]'::jsonb,2,'Detail finish.','original'),
('127.881.d.4.F',4,'A final detailing step is done before delivery so the vehicle:','["has overspray", "is unfinished", "is dirty", "is clean and ready to hand over to the customer"]'::jsonb,3,'Customer-ready.','original'),
('127.881.d.5.A',3,'A painter uses a gauge to measure film thickness on an old finish before sanding. She is:','["inspecting and identifying the type of finish, surface condition and film thickness", "skipping tests", "guessing thickness", "ignoring paint"]'::jsonb,0,'Measure the film.','original'),
('127.881.d.5.A',4,'High film thickness readings warn a painter that:','["more paint is better", "too many layers may require stripping instead of another coat", "no sanding is needed", "the panel is thin"]'::jsonb,1,'Too much film.','original'),
('127.881.d.5.B',3,'Using 320-grit on a block, a painter smooths the edge of a chip so the old paint tapers into bare metal. She is:','["masking", "detailing", "featheredging areas to be refinished", "buffing"]'::jsonb,2,'Taper the edge.','original'),
('127.881.d.5.B',4,'Featheredging is done so that the repair edge:','["creates a ridge", "shows clearly", "adds a color", "won''t show through the new finish"]'::jsonb,3,'No visible edge.','original'),
('127.881.d.5.C',3,'After sanding to bare metal, a painter applies an etching primer to the steel. She is:','["applying a suitable metal treatment or primer", "detailing", "masking", "buffing"]'::jsonb,0,'Treat bare metal.','original'),
('127.881.d.5.C',4,'Metal treatment primer on bare steel is used to:','["thin the coat", "help adhesion and resist corrosion", "speed rust", "remove paint"]'::jsonb,1,'Adhesion and protection.','original'),
('127.881.d.5.D',3,'Before spraying, Rae masks the windows, trim and adjacent panels with paper and tape. She is:','["spraying", "buffing", "masking and protecting areas that will not be refinished", "sanding"]'::jsonb,2,'Protect nearby surfaces.','original'),
('127.881.d.5.D',4,'Tape lines that aren''t pressed down can allow:','["perfect lines", "faster work", "no mess", "overspray and fuzzy edges"]'::jsonb,3,'Seal the edge.','original'),
('127.881.d.5.E',3,'A painter mixes primer-surfacer with its reducer and activator, following the data sheet ratio. She is:','["mixing primer, primer-surfacer or primer-sealer", "painting clearcoat", "sanding", "polishing"]'::jsonb,0,'Mix primer.','original'),
('127.881.d.5.E',4,'A primer-surfacer is built to:','["dry instantly", "fill minor sanding scratches so the surface is smooth", "add color", "remove rust"]'::jsonb,1,'Fill and level.','original'),
('127.881.d.5.F',3,'A painter picks a gray undercoat shade that best helps a weak red topcoat cover in fewer coats. She is:','["ignoring color", "using clear", "identifying a complementary color or shade of undercoat to improve coverage", "picking a random shade"]'::jsonb,2,'Undercoat shade.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_132'
from (values
('127.881.d.5.F',4,'A shade of undercoat that matches the topcoat can improve:','["thin metal", "film cracks", "rust", "hiding and reduce the number of topcoat layers"]'::jsonb,3,'Better hiding.','original'),
('127.881.d.5.G',3,'A painter sprays two even coats of primer over the repaired spot, allowing flash time between coats. She is:','["applying primer onto the surface of the repaired area", "detailing", "buffing", "removing decals"]'::jsonb,0,'Prime the repair.','original'),
('127.881.d.5.G',4,'Applying primer too heavily in one pass can cause:','["dry spray", "runs and long cure times", "perfect leveling", "faster drying"]'::jsonb,1,'Light even coats.','original'),
('127.881.d.5.H',3,'A painter blows out cracks and moldings with an air gun before wiping the surface. She is:','["sanding", "painting", "removing dust from the area to be refinished, including cracks and moldings", "adding dust"]'::jsonb,2,'Clear hidden dust.','original'),
('127.881.d.5.H',4,'Dust left in a crack can later:','["stay locked in", "improve the finish", "cure the paint", "blow out onto the wet paint and cause dirt defects"]'::jsonb,3,'Blowout risk.','original'),
('127.881.d.5.I',3,'Using a lint-free cloth, a painter wipes the panel with a wax and grease remover then dries it with a second clean cloth. She is:','["cleaning the area with a final cleaning solution", "sanding", "masking", "buffing"]'::jsonb,0,'Final clean.','original'),
('127.881.d.5.I',4,'A two-rag wipe method is used so that:','["paint dries", "dissolved contaminants are removed, not smeared back", "contaminants spread", "cloth wears faster"]'::jsonb,1,'Wet then dry.','original'),
('127.881.d.5.J',3,'Right before spraying, a painter gently drags a tack cloth over the panel. She is:','["masking", "sanding", "removing dust or lint particles with a tack cloth", "buffing"]'::jsonb,2,'Last dust pass.','original'),
('127.881.d.5.J',4,'Pressing hard with a tack cloth is avoided because it can:','["improve the finish", "remove all dust", "dry the panel", "leave a sticky residue that hurts adhesion"]'::jsonb,3,'Light touch.','original'),
('127.881.d.5.K',3,'A painter rolls a sealer over primer to keep the topcoat from soaking in and to get an even color. She is:','["applying a suitable sealer to the area being refinished", "masking", "detailing", "buffing"]'::jsonb,0,'Sealer step.','original'),
('127.881.d.5.K',4,'A primer-sealer is used to:','["thin paint", "create a uniform barrier between old finish and new paint", "remove color", "add shine"]'::jsonb,1,'Barrier layer.','original'),
('127.881.d.5.L',3,'A painter sprays a chip-resistant coating on the lower rocker panels before color to resist road debris. She is:','["buffing", "detailing", "applying a stone chip resistant coating", "masking"]'::jsonb,2,'Chip protection.','original'),
('127.881.d.5.L',4,'Stone chip coating is most useful on:','["the roof center", "the windshield glass", "the interior", "lower panels and rocker areas hit by road debris"]'::jsonb,3,'Common chip zones.','original'),
('127.881.d.5.M',3,'A technician checks the part''s stamped code to learn whether a bumper is rigid or flexible and picks the right flex additive. She is:','["identifying types of plastic parts to be refinished", "masking", "buffing", "painting"]'::jsonb,0,'Know the plastic.','original'),
('127.881.d.5.M',4,'Paint on a flexible bumper often needs a flex additive to:','["make it harder", "prevent cracking when the part bends", "speed drying", "increase rust"]'::jsonb,1,'Add flexibility.','original'),
('127.881.d.5.N',3,'A painter identifies a galvanized steel panel and a bare aluminum panel and picks the correct primer for each. She is:','["using one primer for all", "ignoring metal types", "identifying metal parts to be refinished and determining materials and preparation needed", "guessing"]'::jsonb,2,'Metal-specific prep.','original'),
('127.881.d.5.N',4,'Etching primer on aluminum is chosen because it:','["removes paint", "dissolves the metal", "adds weight", "bites into the oxide layer for good adhesion"]'::jsonb,3,'Adhesion on aluminum.','original'),
('127.881.d.6.A',3,'At the start of a shift, Amir takes apart his spray gun, cleans the cap and checks the booth and the air line for water. He is:','["inspecting, cleaning and determining the condition of spray guns, the spray environment and related equipment", "spraying first", "ignoring equipment", "skipping cleaning"]'::jsonb,0,'Check equipment.','original'),
('127.881.d.6.A',4,'A dirty gun cap or clogged air passage can cause:','["a perfect pattern", "spitting and a distorted spray pattern", "a cleaner finish", "less paint use"]'::jsonb,1,'Dirty gun, bad pattern.','original'),
('127.881.d.6.B',3,'Reading the data sheet, a painter picks a 1.3 mm fluid tip for basecoat and a 1.4 mm for clear. She is:','["using one tip for all", "guessing tip sizes", "selecting spray gun setup, including fluid needle, nozzle and cap, for the product being applied", "ignoring directions"]'::jsonb,2,'Match tip to material.','original'),
('127.881.d.6.B',4,'A thicker primer-surfacer generally needs:','["a dry tip", "a smaller tip", "no tip", "a larger fluid tip than thin basecoat"]'::jsonb,3,'Heavier material, larger tip.','original'),
('127.881.d.6.C',3,'Before spraying a test card, Kim adjusts the fluid knob, the air inlet pressure and the fan pattern knob. She is:','["testing and adjusting a spray gun with fluid, air and pattern control valves", "sanding", "cleaning rags", "painting a car"]'::jsonb,0,'Dial in the gun.','original'),
('127.881.d.6.C',4,'A spray pattern that is heavy in the middle and thin at the ends usually means:','["a clean gun", "the fan is too narrow or the air pressure is too low", "a perfect pattern", "too much sanding"]'::jsonb,1,'Pattern fault.','original'),
('127.881.d.6.D',3,'A painter explains that a pressure pot pushes paint to the gun with air pressure instead of relying on gravity. She is describing:','["a tire changer", "a sander", "the operation of pressure spray equipment", "a wash bay"]'::jsonb,2,'Pressure feed.','original'),
('127.881.d.6.D',4,'A pressure spray system is chosen for large jobs because it:','["dries paint", "stops spraying", "uses no air", "delivers a steady supply of heavy material to the gun"]'::jsonb,3,'Steady supply.','original'),
('127.881.d.7.A',3,'A painter finds the paint code on the vehicle information label in the door jamb. She is:','["identifying the color code from the manufacturer''s vehicle information label", "guessing the color", "ignoring the label", "using the VIN only"]'::jsonb,0,'Find the code.','original'),
('127.881.d.7.A',4,'The paint code is used by the shop to:','["set tire pressure", "look up the formula for the right color", "pick tire size", "find the owner"]'::jsonb,1,'Code leads to formula.','original'),
('127.881.d.7.B',3,'Marco measures, stirs and strains the mixed paint through a filter before filling the cup. He is:','["spraying dry", "skipping mixing", "measuring, shaking, stirring, reducing, activating and straining refinish materials", "adding water randomly"]'::jsonb,2,'Proper mixing.','original'),
('127.881.d.7.B',4,'Straining paint before spraying helps by:','["adding dirt", "drying paint", "thinning color", "catching lumps and debris that cause defects"]'::jsonb,3,'Strain debris.','original'),
('127.881.d.7.C',3,'A painter holds the gun 6 to 8 inches from the panel, keeps it square and overlaps each pass by half. She is applying:','["appropriate spray techniques, including arc, angle, distance and overlap", "a dip method", "random sweeps", "a brush stroke"]'::jsonb,0,'Technique basics.','original'),
('127.881.d.7.C',4,'Tilting the gun at an angle at the end of a pass causes:','["perfect blends", "uneven film thickness and color shift", "faster drying", "even paint"]'::jsonb,1,'Keep it square.','original'),
('127.881.d.7.D',3,'Before painting the car, Jo sprays a test panel and holds it next to the fender to compare color. She is:','["polishing", "skipping a test", "applying product on a test panel and checking for color match", "guessing"]'::jsonb,2,'Test the match.','original'),
('127.881.d.7.D',4,'Color should be checked under:','["a dark room", "the booth floor", "no light", "more than one light source"]'::jsonb,3,'Metamerism.','original'),
('127.881.d.7.E',3,'On a work truck, a painter sprays one color with the gloss built in, without a separate clear. She is applying:','["a single-stage topcoat", "a primer", "a basecoat/clearcoat", "a sealer"]'::jsonb,0,'One-step color and gloss.','original'),
('127.881.d.7.E',4,'A single-stage finish differs from basecoat/clearcoat because it:','["has no gloss", "has color and gloss in one product", "needs two products", "has no color"]'::jsonb,1,'One product.','original'),
('127.881.d.7.F',3,'A painter blends basecoat into a door and then sprays clear over the repair panel. She is:','["detailing", "priming only", "applying basecoat and clearcoat for panel blending and panel refinishing", "sanding only"]'::jsonb,2,'Blend and clear.','original'),
('127.881.d.7.F',4,'The clearcoat is applied over basecoat to:','["remove color", "thin the paint", "soften the metal", "protect the color and add gloss"]'::jsonb,3,'Clear protects.','original'),
('127.881.d.7.G',3,'For a full repaint, a painter sprays color on every panel and then clear on the whole car. She is applying:','["basecoat and clearcoat for overall refinishing", "a spot repair", "a wash", "a decal"]'::jsonb,0,'Overall refinish.','original'),
('127.881.d.7.G',4,'Overall refinishing differs from a spot repair because:','["it skips prep", "every panel is painted instead of one area", "no color is used", "no clear is needed"]'::jsonb,1,'Whole vehicle.','original'),
('127.881.d.7.H',3,'After the basecoat dries, Ben removes a few dust nibs with fine paper before clear. He is:','["masking", "buffing clear", "removing nibs or imperfections from the basecoat", "adding nibs"]'::jsonb,2,'Clean the base.','original'),
('127.881.d.7.H',4,'Heavy sanding of metallic basecoat can cause:','["faster dry", "a stronger finish", "perfect color", "cloudy or mottled color"]'::jsonb,3,'Light touch.','original'),
('127.881.d.7.I',3,'A painter adds an adhesion promoter to a rigid plastic mirror housing before color. She is:','["refinishing rigid or semi-rigid plastic parts", "painting wheels", "refinishing steel", "detailing glass"]'::jsonb,0,'Plastic prep.','original'),
('127.881.d.7.I',4,'Rigid plastic can be painted without flex additive because it:','["is soft", "does not bend during normal use", "bends easily", "cracks constantly"]'::jsonb,1,'No flex needed.','original'),
('127.881.d.7.J',3,'A painter adds flex agent to the clearcoat for a bumper cover that bends in a light impact. She is:','["detailing glass", "masking", "refinishing flexible plastic parts", "refinishing metal"]'::jsonb,2,'Flexible plastic.','original'),
('127.881.d.7.J',4,'Without a flex agent, a hardened coating on a bumper may:','["bounce back", "stay perfect", "get stronger", "crack or flake when the part flexes"]'::jsonb,3,'Cracking.','original'),
('127.881.d.7.K',3,'A tri-coat pearl white requires a basecoat, a mid-coat and a clear. The painter is applying:','["multi-stage coats for panel blending and overall refinishing", "a single coat", "only clear", "only primer"]'::jsonb,0,'Tri-coat.','original'),
('127.881.d.7.K',4,'On a tri-coat finish, the number of mid-coat passes affects:','["the fuel type", "the final color appearance", "tire pressure", "the owner''s name"]'::jsonb,1,'Mid-coat controls color.','original'),
('127.881.d.7.L',3,'A painter looks up a formula and weighs each toner on a scale to match the code. She is:','["using random toners", "guessing", "identifying and mixing paint using a formula", "using a brush"]'::jsonb,2,'Formula mixing.','original'),
('127.881.d.7.L',4,'Weighing toners in grams instead of eyeballing helps ensure:','["a random color", "wasted paint", "a faded color", "the color matches the formula repeatably"]'::jsonb,3,'Weigh for accuracy.','original'),
